  @Override public boolean equals(Object other) {
    if (!(other instanceof TerminalInputResult that)) return false;
    return Objects.deepEquals(sessionId, that.sessionId) && Objects.deepEquals(serverSequence, that.serverSequence) && Objects.deepEquals(frameSequence, that.frameSequence) && Objects.deepEquals(correlationId, that.correlationId) && Objects.deepEquals(disposition, that.disposition) && Objects.deepEquals(selectionPresent, that.selectionPresent) && Objects.deepEquals(selection, that.selection);
  }
